def compute_sequence(N=15):
    # a[i] stores a_{i+1}
    a = [0] * N

    # Base cases
    a[0] = 1  # a_1
    a[1] = 1  # a_2

    print("--- Initial Values ---")
    print(f"a_1 = {a[0]}")
    print(f"a_2 = {a[1]}")

    # Calculate a_n for n = 3 to N (i = 2 to N-1)
    for i in range(2, N):
        n = i + 1 # Current term index (n)

        # a_{n-1} is stored at a[i-1]
        a_n_minus_1 = a[i-1]

        # Calculation: a_n = a_{a_{n-1}} + a_{n - a_{n-1}}

        # Term 1: a_{a_{n-1}}
        idx1 = a_n_minus_1 - 1
        if idx1 < 0 or idx1 >= i:
            val1 = "ERROR_BOUNDS"
        else:
            val1 = a[idx1]

        # Term 2: a_{n - a_{n-1}}
        target_n2 = n - a_n_minus_1

        if target_n2 <= 0:
            val2 = "ERROR_BOUNDS"
        else:
            idx2 = target_n2 - 1
            if idx2 >= i:
                 val2 = "ERROR_BOUNDS"
            else:
                 val2 = a[idx2]


        # Calculate a_n
        if isinstance(val1, int) and isinstance(val2, int):
            a_n = val1 + val2
        else:
            a_n = f"ERROR_CALC: {val1}, {val2}"

        a[i] = a_n

        # Log all intermediate steps
        print(f"\n--- a_{n} Calculation ---")
        print(f"a_{n-1} = {a_n_minus_1}")

        # Log Term 1
        if isinstance(val1, int):
            print(f"T1: a_{a_n_minus_1} = {val1}")
        else:
            print(f"T1: {val1}")

        # Log Term 2
        if isinstance(val2, int):
            print(f"T2: a_{n - a_n_minus_1} = {val2}")
        else:
            print(f"T2: {val2}")

        print(f"a_{n} = {val1} + {val2} = {a_n}")


    print("\n======================================")
    print("Final sequence a_1 to a_15:")
    print(a)
    print("======================================")
    return a

